CREATE TABLE IF NOT EXISTS proyectos (id TEXT PRIMARY KEY,codigo TEXT NOT NULL,nombre TEXT NOT NULL,empresa TEXT NOT NULL CHECK(empresa IN ('STEEL','IEM')),activo INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
    CREATE TABLE IF NOT EXISTS colaboradores (id TEXT PRIMARY KEY,codigo TEXT NOT NULL,nombre TEXT NOT NULL,puesto TEXT NOT NULL,area TEXT NOT NULL,estado TEXT NOT NULL CHECK(estado IN ('Activo','Inactivo')),creado TEXT NOT NULL DEFAULT(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),version INTEGER NOT NULL DEFAULT 1);
    CREATE TABLE IF NOT EXISTS usuarios (id TEXT PRIMARY KEY,usuario TEXT NOT NULL,nombre TEXT NOT NULL,rol TEXT NOT NULL CHECK(rol IN ('Administrador','Registro','Consulta')),activo INTEGER NOT NULL DEFAULT 1,clave TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
    CREATE TABLE IF NOT EXISTS sesiones (token TEXT PRIMARY KEY,usuario_id TEXT NOT NULL REFERENCES usuarios(id),vence BIGINT NOT NULL);
    CREATE TABLE IF NOT EXISTS proveedores (id TEXT PRIMARY KEY,codigo TEXT NOT NULL,nombre TEXT NOT NULL,contacto TEXT NOT NULL DEFAULT '',activo INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
    CREATE TABLE IF NOT EXISTS articulos (id TEXT PRIMARY KEY,codigo TEXT NOT NULL,descripcion TEXT NOT NULL,variante TEXT NOT NULL DEFAULT '',unidad TEXT NOT NULL DEFAULT 'Unidad',ficha_url TEXT NOT NULL DEFAULT '',minimo INTEGER NOT NULL DEFAULT 0,activo INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
    CREATE TABLE IF NOT EXISTS articulo_proveedor (articulo_id TEXT NOT NULL REFERENCES articulos(id),proveedor_id TEXT NOT NULL REFERENCES proveedores(id),codigo_proveedor TEXT NOT NULL DEFAULT '',PRIMARY KEY(articulo_id,proveedor_id));
    CREATE TABLE IF NOT EXISTS ubicaciones (id TEXT PRIMARY KEY,codigo TEXT NOT NULL,nombre TEXT NOT NULL,tipo TEXT NOT NULL CHECK(tipo IN ('Bodega','Proyecto')),empresa TEXT NOT NULL CHECK(empresa IN ('STEEL','IEM')),proyecto_id TEXT REFERENCES proyectos(id),activo INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
    CREATE TABLE IF NOT EXISTS saldos (articulo_id TEXT NOT NULL REFERENCES articulos(id),ubicacion_id TEXT NOT NULL REFERENCES ubicaciones(id),cantidad INTEGER NOT NULL CHECK(cantidad>=0),PRIMARY KEY(articulo_id,ubicacion_id));
    CREATE TABLE IF NOT EXISTS movimientos (orden BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,solicitud TEXT NOT NULL UNIQUE,contenido TEXT NOT NULL,tipo TEXT NOT NULL,articulo_id TEXT NOT NULL REFERENCES articulos(id),origen_id TEXT REFERENCES ubicaciones(id),destino_id TEXT REFERENCES ubicaciones(id),cantidad INTEGER NOT NULL,fecha TEXT NOT NULL,motivo TEXT NOT NULL,usuario_id TEXT NOT NULL REFERENCES usuarios(id),creado TEXT NOT NULL DEFAULT(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
    CREATE TABLE IF NOT EXISTS lineas_movimiento (movimiento_id TEXT NOT NULL REFERENCES movimientos(id),articulo_id TEXT NOT NULL REFERENCES articulos(id),ubicacion_id TEXT NOT NULL REFERENCES ubicaciones(id),delta INTEGER NOT NULL);
    CREATE INDEX IF NOT EXISTS lineas_saldo ON lineas_movimiento(articulo_id,ubicacion_id);
    CREATE TABLE IF NOT EXISTS auditoria (orden BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,fecha TEXT NOT NULL DEFAULT(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),usuario_id TEXT,accion TEXT NOT NULL,entidad TEXT NOT NULL,registro_id TEXT NOT NULL);
  CREATE TABLE IF NOT EXISTS catalogo_capacitaciones(id TEXT PRIMARY KEY,nombre TEXT NOT NULL,clave TEXT NOT NULL UNIQUE,descripcion TEXT NOT NULL DEFAULT '',activo INTEGER NOT NULL DEFAULT 1);CREATE TABLE IF NOT EXISTS capacitaciones(orden BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,solicitud TEXT NOT NULL UNIQUE,contenido TEXT NOT NULL,tema TEXT NOT NULL,curso_clave TEXT NOT NULL,fecha TEXT NOT NULL,instructor TEXT NOT NULL,lugar TEXT NOT NULL,observaciones TEXT NOT NULL,usuario_id TEXT NOT NULL REFERENCES usuarios(id),anulada INTEGER NOT NULL DEFAULT 0,motivo_anulacion TEXT,creado TEXT NOT NULL DEFAULT(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
    CREATE TABLE IF NOT EXISTS constancias(id TEXT PRIMARY KEY,capacitacion_id TEXT NOT NULL REFERENCES capacitaciones(id),colaborador_id TEXT NOT NULL REFERENCES colaboradores(id),vence TEXT,UNIQUE(capacitacion_id,colaborador_id));
    CREATE TABLE IF NOT EXISTS avisos_leidos(usuario_id TEXT NOT NULL REFERENCES usuarios(id),constancia_id TEXT NOT NULL REFERENCES constancias(id),estado TEXT NOT NULL,PRIMARY KEY(usuario_id,constancia_id,estado));CREATE TABLE IF NOT EXISTS solicitudes_usuario(id TEXT PRIMARY KEY,usuario TEXT NOT NULL,nombre TEXT NOT NULL,clave TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'Pendiente' CHECK(estado IN ('Pendiente','Aprobada','Rechazada')),creado TEXT NOT NULL DEFAULT(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),usuario_id TEXT REFERENCES usuarios(id));
CREATE UNIQUE INDEX IF NOT EXISTS proyectos_codigo_ci ON proyectos(lower(codigo));
CREATE UNIQUE INDEX IF NOT EXISTS colaboradores_codigo_ci ON colaboradores(lower(codigo));
CREATE UNIQUE INDEX IF NOT EXISTS usuarios_usuario_ci ON usuarios(lower(usuario));
CREATE UNIQUE INDEX IF NOT EXISTS proveedores_codigo_ci ON proveedores(lower(codigo));
CREATE UNIQUE INDEX IF NOT EXISTS articulos_codigo_ci ON articulos(lower(codigo));
CREATE UNIQUE INDEX IF NOT EXISTS ubicaciones_codigo_ci ON ubicaciones(lower(codigo));
CREATE UNIQUE INDEX IF NOT EXISTS solicitudes_usuario_usuario_ci ON solicitudes_usuario(lower(usuario));
ALTER TABLE colaboradores ADD COLUMN IF NOT EXISTS empresa TEXT CHECK(empresa IN ('STEEL','IEM'));
ALTER TABLE colaboradores ADD COLUMN IF NOT EXISTS proyecto_id TEXT REFERENCES proyectos(id);
ALTER TABLE colaboradores ADD COLUMN IF NOT EXISTS datos_origen TEXT;
ALTER TABLE articulos ADD COLUMN IF NOT EXISTS datos_origen TEXT;
ALTER TABLE catalogo_capacitaciones ADD COLUMN IF NOT EXISTS datos_origen TEXT;
ALTER TABLE capacitaciones ADD COLUMN IF NOT EXISTS catalogo_id TEXT REFERENCES catalogo_capacitaciones(id);
ALTER TABLE capacitaciones ADD COLUMN IF NOT EXISTS modalidad TEXT NOT NULL DEFAULT 'Grupal';
CREATE TABLE IF NOT EXISTS importaciones_excel(hash TEXT PRIMARY KEY,fecha TEXT NOT NULL,resumen TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS migraciones_soha(clave TEXT PRIMARY KEY,fecha TEXT NOT NULL,resumen TEXT NOT NULL);
